#!/usr/bin/env python3
"""Russia flagship course data, part 3 (HELD for a lawyer's check). RU-17 to RU-24. Own wording; no names; no fees."""

COURSES = [
dict(id="RU-17", title="Art", level="L4 Practitioner",
 summary="Learn to plan, make, document, price and present original artworks as a working artist, with honest records and fair dealing with buyers and galleries.",
 outcomes=[("Understand", "Explain how medium, surface, composition and colour work together to carry meaning in a finished work."),
  ("Apply", "Produce a coherent series of six works from sketches, studies and a written concept."),
  ("Analyse", "Compare the cost of materials, time and overhead to set a defensible price for each work."),
  ("Evaluate", "Judge your own work and a peer's work against stated criteria and give usable feedback."),
  ("Create", "Build a portfolio, a condition-and-provenance record and an exhibition plan for a small show.")],
 task="Make a series of six related works and prepare them for a small public show.",
 condition="Over 8 weeks, using your own studio space, chosen medium, a camera or phone, a tape measure and a spreadsheet.",
 standard="Six finished works, each with a one-page record (title, size in cm, medium, date, price in RUB, condition); photos at 3000 px on the long side; pricing sheet that adds up; pass mark 8 of 10 on the check and no rubric row at Not yet.",
 who="Self-taught or trained makers who want to sell or exhibit work in a structured way.",
 req="Basic drawing or painting skill in one medium; space and materials for it; a phone camera.",
 safety="Art materials can be hazardous: solvents, pigments with heavy metals, resins, dust and kilns need ventilation, labelled storage and protective gear; follow the maker's data sheet. Export or sale of works that may count as cultural property can need permission from the competent Russian authority, and tax treatment of sales differs by status. Check with the competent Russian authority and a local adviser before selling or shipping abroad. No course can promise sales or fame.",
 evidence="Evidence: sketchbook pages, six finished works with records, a pricing sheet, a photo set, an artist statement and an exhibition plan.",
 modules=[
 ("Looking and concept", "Understand", 4, "Work begins with a question you can state. A concept in two sentences guides every later choice of size, colour and surface. Test the concept by asking whether a stranger could guess it from the title and one sketch; if not, narrow it before you buy materials.",
  ["Describe a work by its elements: line, shape, tone, colour, texture, space.", "Write a concept in two sentences: subject plus the feeling or idea you want the viewer to reach.", "Collect 10 references and note what you take from each (not copy).", "Set limits for a series: one palette of 5 colours, one format, one theme.", "Keep a dated sketchbook; it is your first record of authorship."],
  "A series on winter light: concept 'cold morning light on old brick'; palette of 5 pigments; format 40 x 50 cm; 12 thumbnail sketches of 6 x 8 cm done in 2 hours, of which 6 are chosen. Check: 12 thumbnails in 2 hours is 10 minutes each; choosing 6 of 12 keeps half, so the other half are dropped without regret.",
  "Write your concept, palette and format, and draw 12 thumbnails. Time each thumbnail at about 10 minutes and mark the six you would develop.", "Concept in two sentences; palette of no more than 5 colours; 6 thumbnails chosen with a reason each. The total sketching time is under 2.5 hours."),
 ("Materials and surfaces", "Apply", 4, "The surface and the medium decide how a work ages. Choose them for permanence, not only for look. A cheap surface that yellows or cracks in five years damages your name and the buyer's trust, so spend on the support first and on the brush second.",
  ["Compare supports: canvas, board, paper, panel; note weight, absorbency and archival quality.", "Match media to supports: oil on primed canvas, watercolour on 300 g/m2 paper, acrylic on board.", "Prepare a surface correctly: size, prime, dry for the time the maker states.", "Store pigments and solvents closed, labelled, away from heat.", "Test colour mixes on a swatch card before the final work."],
  "A 50 x 70 cm canvas needs about 0.35 m2 of priming. Two coats at 120 mL per m2 give 84 mL; at 900 RUB per litre that is about 76 RUB of primer. Check: 0.5 x 0.7 = 0.35; 0.35 x 2 x 120 = 84 mL = 0.084 L; 0.084 x 900 = 75.6 RUB. Six works of this size need about 454 RUB of primer.",
  "Prepare two surfaces and one swatch card of your palette. Note size, coats, drying time and primer cost for each surface.", "Surfaces primed evenly and dried to the stated time; swatch card labelled with each mix. Primer cost per surface is calculated within 5 RUB."),
 ("Composition and colour", "Analyse", 4, "A strong picture is organised. Composition guides the eye; colour sets mood and depth. Decide the value pattern before the colours, since a picture that works in three tones will survive almost any palette.",
  ["Test a design with thumbnails: rule of thirds, diagonals, centre weight, edge tension.", "Plan a tonal map in three values: light, mid, dark, before adding colour.", "Use warm and cool contrast to push forms forward or back.", "Check a work in black and white on a phone to see if the value structure holds.", "Judge balance by turning the work upside down."],
  "On a 40 x 50 cm work the focal point sits at 2/3 across: 26.7 cm from the left edge. A dark mass takes about 20 percent of the area, mid tones 50 percent, lights 30 percent. Check: 20 + 50 + 30 = 100 percent. On the 2,000 cm2 surface (40 x 50) the dark mass covers 400 cm2, mid tones 1,000 cm2 and lights 600 cm2.",
  "Analyse three of your thumbnails with a value map and choose the strongest. Use squares of 10 x 10 cm so the percentages can be counted.", "Value map for each; choice justified in two sentences. The three values add to 100 percent and the focal point position is given in cm."),
 ("Making the series", "Apply", 5, "Six works in a row teach more than one perfect work. Plan time, make in stages and review. Keep the series moving by working on two or three pieces at once, so that one can dry while another is developed.",
  ["Break a work into stages: underlayer, blocking in, development, details, finish.", "Schedule: for example 6 works at 12 hours each is 72 hours; at 9 hours a week that is 8 weeks.", "Review each work after a day away and note one change.", "Keep drying and varnishing times in the plan.", "Stop when the concept is clear, not when every area is busy."],
  "Plan: 72 hours of making plus 8 hours for varnish, photos and records, 80 hours in total. At 10 hours a week the series takes 8 weeks. Check: 72 + 8 = 80 hours; 80 / 10 = 8 weeks. At 9 hours a week the same series needs 80 / 9 = 8.9 weeks, so allow nine.",
  "Finish the six works with a stage log for each. Record hours per stage and any change from the plan.", "Six works complete; stage log dated; each work reviewed once. Total logged hours are within 10 percent of the 80 hour plan (72 to 88)."),
 ("Records, condition and provenance", "Apply", 3, "A buyer trusts a work with a clear record. Records also protect you if a work is lost or disputed. Records are cheap to make while the work is fresh and almost impossible to rebuild years later, so make them the day the work is finished.",
  ["Make a one-page record: title, year, size in cm, medium, support, edition (if any), price in RUB, location.", "Photograph the whole work, a detail and the signature, on a grey background with even light.", "Note the condition at sale and give care advice: keep out of direct sun, humidity 40 to 60 percent.", "Keep copies of invoices and agreements.", "Number your works so each can be traced."],
  "Record numbering AB-2026-03 means artist code AB, year 2026, third work. A 50 x 70 cm oil on canvas priced at 54,000 RUB has a record, 3 photos at 3000 px and a care card. Check: numbering is unique because the final number counts up; six works get AB-2026-01 to AB-2026-06. Three photos of six works means 18 images to name and file.",
  "Complete records and photos for all six works. Name each photo file with the record number.", "Each record has all fields; photos sharp and square on; numbering is unique. All 18 photos are filed and each file name matches its record."),
 ("Pricing", "Analyse", 3, "A price should cover costs and time and match the market for your level. Guesswork leads to loss or unsold work. Raise the price slowly and only when work sells quickly, and never undercut your own earlier price, which upsets earlier buyers.",
  ["Add materials, framing, your hours at a fair hourly rate, and overhead.", "Compare with prices of similar work by artists at your stage.", "Use a price per cm2 only as a check, not a rule.", "Keep one price list; do not change it between buyers.", "Account for gallery commission when selling through one."],
  "Materials 3,500 RUB + frame 4,000 RUB + 12 hours at 600 RUB = 7,200 RUB + overhead 10 percent. Subtotal 14,700 RUB, plus 1,470 RUB gives 16,170 RUB; with a 40 percent gallery share the retail price is 26,950 RUB. Check: 3,500 + 4,000 = 7,500; 12 x 600 = 7,200; 7,500 + 7,200 = 14,700; 14,700 x 0.1 = 1,470; 14,700 + 1,470 = 16,170; 16,170 / 0.6 = 26,950. The gallery keeps 40 percent, 10,780 RUB, and you receive 16,170 RUB.",
  "Build a price sheet for all six works with the working shown. Include the retail price if a gallery takes 40 percent.", "Sheet adds up; comparison source stated; commission handled. Each retail price equals cost divided by 0.6 where a gallery is used."),
 ("Presenting and selling", "Create", 4, "Presentation turns a pile of work into a show. A clear statement and fair terms make a sale easier. Say the same thing in the statement, the labels and the sale agreement, so a visitor sees one confident voice.",
  ["Write an artist statement of 120 words: what, how, why.", "Plan a hang: eye level centre at about 150 cm, 8 to 10 cm between frames.", "Draft a simple sale agreement: price, payment, delivery, return terms.", "Handle sales taxes and registration as the competent Russian authority requires.", "Ship safely: corner protection, rigid box, insurance for value."],
  "A wall of 4 m fits three 50 cm works with gaps of 25 cm: 3 x 50 + 2 x 25 = 200 cm, centred with 100 cm free each side. Check: 3 x 50 = 150, 2 x 25 = 50, 150 + 50 = 200; 400 - 200 = 200, and 200 / 2 = 100 cm.",
  "Write your statement, hang plan and agreement. Draw a scale plan on 1 to 20 paper for a 4 m wall.", "Statement is 100 to 140 words; plan to scale; agreement has price, payment and delivery. Every gap on the plan is measured in cm."),
 ("Review and next steps", "Evaluate", 3, "A mature practice reviews itself. Honest critique and a plan keep the work moving. Ask the same five questions of every series, so you can compare one project with the next and see real progress.",
  ["Use criteria: concept, craft, composition, originality, finish.", "Give peer feedback that is specific, kind and testable.", "Compare time spent with income to see whether the practice is sustainable.", "Set three goals for the next 6 months.", "Keep a list of venues and calls for work."],
  "Series earned 53,900 RUB from 2 sales at 26,950 RUB against 80 hours and 11,000 RUB of costs: after costs 42,900 RUB, about 536 RUB per hour. Check: 2 x 26,950 = 53,900; 53,900 - 11,000 = 42,900; 42,900 / 80 = 536.25. This is before tax and without any unsold works.",
  "Hold one peer critique and write a six-month plan. Include a table of hours, costs and income for the series.", "Critique uses the five criteria; plan has three dated goals. Hourly income is computed from hours and costs.")],
 quiz=[("Why write a concept before painting?", "It guides choices of size, colour and surface and keeps a series coherent. It also lets you explain the work to a buyer in two sentences."),
  ("Name three elements used to describe a work.", "Line, shape, tone, colour, texture or space. Naming them lets you compare works and give feedback that is specific."),
  ("Why test a work in black and white?", "To see whether the value structure works without colour. If the picture looks flat in grey, the light and dark masses need to be reorganised."),
  ("What must a record of a work include?", "Title, year, size, medium, support, price and location, with photos. Condition and care advice should be added at the time of sale."),
  ("Which factors go into a price?", "Materials, framing, hours at a fair rate, overhead and any commission. Add them line by line so the price can be explained to a buyer."),
  ("Calculate: 12 hours at 600 RUB plus 7,500 RUB materials.", "7,200 + 7,500 = 14,700 RUB before overhead. Adding 10 percent overhead (1,470 RUB) gives 16,170 RUB."),
  ("Why keep a dated sketchbook?", "It records authorship and development. Dated pages help if ownership is questioned and show how a series grew."),
  ("How should solvents be stored?", "Closed, labelled, away from heat, with ventilation. Follow the maker's data sheet and keep them out of reach of children."),
  ("What is a safe humidity range for storing works?", "About 40 to 60 percent. Avoid direct sun and damp walls, which cause cracking, mould and fading."),
  ("Who should you consult before exporting a work?", "The competent Russian authority and a local adviser. Export of cultural property may need permission, so ask before you ship.")],
 rubric=[("Concept and coherence", "No clear idea; works unrelated.", "Concept is stated and works fit it.", "Series develops the idea with insight."),
  ("Craft and finish", "Surface problems; unfinished areas.", "Sound surface and finish.", "Consistently refined work."),
  ("Records and photos", "Missing fields or poor photos.", "Complete records; clear photos.", "Records help a buyer or curator at once."),
  ("Pricing", "Price unsupported.", "Price adds up with working shown.", "Price tested against comparisons."),
  ("Presentation and review", "Plan vague; no critique.", "Hang plan and critique done.", "Plan to scale; critique changes the work.")],
 ladder=["L1 Basic: name tools and materials and make a simple drawing with help.", "L2 Awareness: explain basic composition and colour and describe a work.", "L3 Foundation: finish a single work with records.", "L4 Practitioner: produce a series, price it and plan a small show.", "L5 Specialist: lead a project with a specialist medium and a documented method.", "L6 Advanced: curate and mentor others and negotiate with venues.", "L7 Super expert: set a recognised body of work and teach the field, with peer-reviewed practice."],
 jobs=[("Studio artist", "Makes and sells original work."), ("Illustrator", "Produces images to a brief."), ("Gallery assistant", "Hangs shows and keeps records."), ("Art technician", "Prepares surfaces, frames and installs work."), ("Art teacher", "Leads classes in a chosen medium.")],
 next="Ceramic Studios, Furniture (design, make, retail) and Marketing for Makers."),

dict(id="RU-18", title="Furniture (design, make, retail)", level="L4 Practitioner",
 summary="Design a simple piece, plan its materials and cutting, build it to a safe standard, cost it and prepare it for retail.",
 outcomes=[("Understand", "Explain how joints, grain direction and moisture decide the strength and life of a piece."),
  ("Apply", "Build a small table or cabinet from a drawing to a tolerance of 1 mm."),
  ("Analyse", "Calculate board use, waste and cost from a cutting list."),
  ("Evaluate", "Judge a finished piece for stability, finish and safety against a checklist."),
  ("Create", "Design a product sheet, price and retail plan with warranty and care terms.")],
 task="Design, build, cost and prepare for sale one small piece of furniture.",
 condition="In 6 weeks in a workshop with hand and power tools, a tape, a square, a moisture meter and a spreadsheet.",
 standard="Piece within 1 mm of drawing on key sizes; timber moisture below 12 percent when assembled; costing within 5 percent of actual; pass mark 8 of 10 on the check.",
 who="Hobbyists and small makers who want to build and sell furniture.",
 req="Basic workshop skill; access to tools and a ventilated space.",
 safety="Woodworking carries risk of cuts, dust, noise and fire. Use guards, push sticks, eye, ear and dust protection, and extraction; do not use machines without training. Finishes can be flammable and toxic; follow the maker's data sheet. Consumer products must meet the relevant federal rules for safety and labelling; check with the competent Russian authority and a local adviser before selling at scale.",
 evidence="Evidence: drawing, cutting list, costing sheet, build log, finished piece with photos, product sheet and care card.",
 modules=[
 ("Design and ergonomics", "Understand", 4, "Furniture fits a body and a room. Standard dimensions are a starting point for a design that works. Sit at a mock-up before cutting good timber, because an error of 50 mm in height is obvious in cardboard and expensive in solid wood.",
  ["Know typical sizes: table height about 750 mm, seat about 450 mm, desk about 720 mm.", "Sketch in plan, front and side views with sizes in mm.", "Check clearance: 900 mm for walking routes, 600 mm behind a chair.", "Choose a style and limit to one main material.", "Build a cardboard mock-up to test proportion."],
  "A dining table for four: top 1200 x 750 mm, height 750 mm. Chair space needs 600 mm each side, so the room needs at least 2400 x 1950 mm free. Check: 1200 + 2 x 600 = 2400 and 750 + 2 x 600 = 1950, which is 4.68 m2 of floor.",
  "Draw a table or cabinet with sizes and make a mock-up. Mark the clearance zones on the floor with tape at full size.", "Three views with sizes; mock-up tested for clearance. Walking routes of 900 mm are shown and every size is in mm."),
 ("Timber, boards and moisture", "Understand", 4, "Wood moves with moisture. Using the right material and drying avoids cracks and warping. Buy timber early and let it settle in the workshop, as a board that moves after assembly will split a good joint.",
  ["Compare solid wood, plywood, MDF and particle board for strength, cost and finish.", "Read grain: keep long grain along load, mark faces and edges.", "Measure moisture with a meter; aim for 8 to 12 percent indoors.", "Allow for movement: solid wood shifts across the grain, not along it.", "Stack boards flat with spacers to acclimatise for at least 1 week."],
  "A solid top 600 mm wide can change about 0.2 percent per 1 percent moisture shift across the grain. A 3 percent change gives 600 x 0.002 x 3 = 3.6 mm of movement. Check: 0.2 percent is 0.002; 600 x 0.002 = 1.2 mm per 1 percent shift; 1.2 x 3 = 3.6 mm. A top fixed rigidly to a frame with no slot would be forced to split.",
  "Measure moisture in three boards and record it. Take readings on the face and the end of each board, and note the date and room temperature.", "Readings recorded; any board above 12 percent set aside. The average and the highest reading are stated, and boards stack with spacers for 1 week."),
 ("Cutting list and costing", "Analyse", 4, "A cutting list turns a drawing into parts. Good planning cuts waste and shows the true cost. Cut the widest parts first, and list the offcuts that can become small parts such as rails or stretchers.",
  ["List each part with length, width, thickness and quantity.", "Add 3 mm per cut for the saw blade and 5 mm trim allowance.", "Nest parts on a board of 2440 x 1220 mm to reduce waste.", "Add hardware, finish, consumables and time.", "Include 10 percent for waste and mistakes."],
  "Parts total 1.9 m2 of 18 mm board; a sheet is 2.98 m2. With 15 percent waste you need 2.19 m2, so one sheet at 3,800 RUB. Hardware 900 RUB, finish 600 RUB, 20 hours at 500 RUB = 10,000 RUB; total 15,300 RUB. Check: 1.9 x 1.15 = 2.185 m2, below the 2.98 m2 of one sheet; 3,800 + 900 + 600 + 10,000 = 15,300. About 64 percent of the sheet (1.9 / 2.98) goes into parts.",
  "Produce a cutting list and cost sheet for your design. Show parts, sheet layout, waste percent, hardware and hours.", "List complete; board use calculated; total adds up. Waste is stated as a percent, and the total is checked twice by a second person."),
 ("Joints and assembly", "Apply", 5, "A joint carries load. The right joint matches the part and the tools available. Practise each joint on an offcut first, because a joint cut well on the third try is better than one forced on the final part.",
  ["Compare butt with screws, dowel, mortise and tenon, dovetail and pocket hole.", "Mark out with a knife and square; cut to the waste side of the line.", "Dry-fit before glue; check square by measuring diagonals.", "Clamp for the glue time the maker states, usually 30 to 60 minutes.", "Wipe squeeze-out and let the glue cure 24 hours before load."],
  "A frame 800 x 500 mm is square when both diagonals are equal: sqrt(800 squared + 500 squared) = 943 mm. A difference over 2 mm means adjust before the glue sets. Check: 800 x 800 = 640,000; 500 x 500 = 250,000; the sum 890,000 has a square root of 943.4 mm. If one diagonal reads 945 and the other 941, the 4 mm difference means pull the frame with a clamp until equal.",
  "Build the carcass or frame and record diagonals. Cut one practice joint of each type on an offcut first.", "Diagonals within 2 mm; joints tight with no gaps over 0.5 mm. Clamp time and cure time are logged, and the frame is not loaded for 24 hours."),
 ("Finishing", "Apply", 3, "A finish protects and shows the grain. Preparation matters more than the product. Test the finish on the same wood and sand it between coats, as one unprepared scratch is magnified by every coat.",
  ["Sand through grits 80, 120, 180, 240; remove dust between steps.", "Choose oil, wax, lacquer or varnish for the use.", "Apply thin coats and sand lightly between them.", "Ventilate; keep rags flat to dry because they can ignite.", "Test on an offcut first."],
  "Three coats of lacquer at 80 mL per m2 on a 1.5 m2 piece use 360 mL. At 1,200 RUB per litre that is 432 RUB. Check: 3 x 80 = 240 mL per m2; 240 x 1.5 = 360 mL; 0.36 L x 1,200 = 432 RUB. A 1 L can covers 1 / 0.24 = 4.2 m2 with three coats.",
  "Finish the piece and one test offcut. Record grits, coat count and drying time between coats.", "Even surface with no runs; offcut shows the same result. Dust is removed before each coat and rags are laid flat to dry."),
 ("Safety and quality check", "Evaluate", 3, "Safe furniture does not tip, trap or shed splinters. A checklist makes the check repeatable. Run the checks yourself and then ask someone else to try to tip, pinch or snag the piece, since makers overlook the faults they built in.",
  ["Test stability: a table should not tip under a 100 N side load at the edge.", "Round sharp edges to at least 2 mm.", "Check for pinch points at hinges and drawers.", "Use fixings rated for the load; anchor tall units to a wall.", "Record the results with date."],
  "A cabinet 1800 mm high and 400 mm deep should be fixed to the wall with two brackets rated for 50 kg each. Check: two brackets give 2 x 50 = 100 kg of rated capacity, about twice a loaded weight of 50 kg, a safety margin of 2.",
  "Run the checklist on your piece. Record the load applied, the result and the fix for each failure.", "All checks recorded; failures fixed and rechecked. Edge radius is measured with a gauge and tall units are anchored."),
 ("Retail and customers", "Create", 4, "Selling needs a clear product sheet, fair terms and care advice. Be honest in the description, since a customer who finds a different size or finish returns the piece and tells others.",
  ["Write a product sheet: size, material, finish, weight, lead time.", "Set a price using cost plus margin and a market check.", "State warranty and return terms honestly.", "Give a care card: avoid direct sun, wipe with a damp cloth.", "Meet the relevant federal rules for consumer sale, labelling and tax."],
  "Cost 15,300 RUB with a 40 percent margin on price: price = 15,300 / 0.6 = 25,500 RUB. Check: 25,500 x 0.6 = 15,300; margin = 25,500 - 15,300 = 10,200 RUB, which is 40 percent of the price. A 40 percent mark-up on cost would give only 21,420 RUB, so know which one you mean.",
  "Write a product sheet, price and care card. Add photos, dimensions in mm, weight and lead time.", "Sheet complete; price worked out; terms in plain words. The margin is stated on price, and warranty and return terms fit half a page."),
 ("Review and scale", "Evaluate", 3, "A first piece teaches the process. A review shows whether it can become a line. Treat the first piece as paid-for learning, and write down what slowed you while it is fresh.",
  ["Compare planned and actual hours and cost.", "List three changes that save time or waste.", "Test demand with a small run of three pieces.", "Plan tool and space needs for a batch.", "Set dates for the next build."],
  "Planned 20 hours, actual 24: variance 20 percent. A jig that saves 3 hours per piece cuts a batch of 3 by 9 hours. Check: (24 - 20) / 20 = 0.2, which is 20 percent; 3 x 3 = 9 hours saved. At 500 RUB per hour that saves 4,500 RUB on the batch.",
  "Write a variance report and a batch plan. Show planned and actual hours for each stage.", "Variance computed; three changes named; batch plan dated. The saving from each change is given in hours and RUB.")],
 quiz=[("What is a typical table height?", "About 750 mm. A seat about 450 mm high lets a person sit with knees clear and forearms level."),
  ("Which moisture level suits indoor furniture?", "About 8 to 12 percent. Above 12 percent the board will shrink after assembly and may open joints or crack."),
  ("Why dry-fit before gluing?", "To check fit and square before the glue sets. Glue gives only a short working time, so errors found afterwards are hard to fix."),
  ("How do you check a frame is square?", "Measure both diagonals; they must be equal. A difference over 2 mm means adjust with a clamp before the glue sets."),
  ("What is the waste allowance in costing?", "About 10 to 15 percent. It covers saw cuts, defects and mistakes, and it is added to the board area before pricing."),
  ("Why keep oily rags flat to dry?", "They can heat and ignite. Drying oil gives off heat as it cures, so lay rags flat outside or soak them in water in a metal container."),
  ("Calculate the price at 40 percent margin on cost 15,300 RUB.", "15,300 / 0.6 = 25,500 RUB. The margin of 10,200 RUB is 40 percent of the price."),
  ("Why anchor tall cabinets?", "To prevent tipping. A child pulling on a drawer can topple a tall unit, so fix it with rated brackets to the wall."),
  ("Which direction does solid wood move most?", "Across the grain. Along the grain movement is very small, so design joints and fixings that let the top shift."),
  ("Who do you ask about product rules?", "The competent Russian authority and a local adviser, before selling at scale, because safety and labelling rules apply to consumer goods.")],
 rubric=[("Design and drawing", "Sizes missing or unworkable.", "Drawing with sizes works in use.", "Design is clear and refined."),
  ("Build accuracy", "Out of square or loose joints.", "Within 1 mm on key sizes.", "Consistent fine fit."),
  ("Costing", "Costs incomplete.", "Total adds up within 5 percent.", "Variance explained and acted on."),
  ("Safety", "Checks skipped.", "Checklist passed.", "Hazards found and removed in design."),
  ("Retail readiness", "No product sheet.", "Sheet, price and terms complete.", "Plan for a batch with demand test.")],
 ladder=["L1 Basic: name tools and make a simple cut with supervision.", "L2 Awareness: explain joints and moisture and read a drawing.", "L3 Foundation: build a simple box or shelf.", "L4 Practitioner: design, build, cost and prepare a piece for sale.", "L5 Specialist: run small batches with jigs and a quality plan.", "L6 Advanced: lead a workshop and set standards.", "L7 Super expert: advise on design, materials and safety across the sector."],
 jobs=[("Furniture maker", "Builds pieces to a design."), ("Joiner", "Makes and fits doors, stairs and fitted units."), ("Furniture designer", "Draws and prototypes products."), ("Finisher", "Sands and finishes surfaces."), ("Retail adviser", "Helps customers choose furniture.")],
 next="Art, Ceramic Studios and Marketing for Makers."),

dict(id="RU-19", title="Insurance", level="L4 Practitioner",
 summary="Understand how insurance works, assess risk, read policies, handle claims and serve customers fairly within the rules.",
 outcomes=[("Understand", "Explain risk pooling, premium, sum insured, excess and exclusions."),
  ("Apply", "Calculate a premium from a base rate and loading factors."),
  ("Analyse", "Compare two policies for cover, limits and exclusions."),
  ("Evaluate", "Judge a claim against policy wording and evidence."),
  ("Create", "Build a customer needs analysis and a compliant record of advice.")],
 task="Assess a customer's need, compare two policies and process a simple claim.",
 condition="In 6 weeks using sample policies, a calculator and a record template.",
 standard="Premium within 1 percent of the model answer; needs analysis covers 5 risk areas; claim file complete with decision reasons; pass mark 8 of 10.",
 who="Newcomers and junior staff in agencies, brokers and insurers.",
 req="Basic arithmetic; no prior insurance work.",
 safety="Insurance is a regulated activity. Selling, advising or settling claims needs the licence, registration or employer authority the competent Russian supervisory authority requires; this course does not grant any of it. Do not give advice beyond your authority. Protect personal data under the relevant federal rules. Never promise a claim will be paid. Check with the competent Russian authority and a local adviser.",
 evidence="Evidence: needs analysis, premium calculation, policy comparison table, claim file and a record of advice.",
 modules=[
 ("How insurance works", "Understand", 4, "Insurance moves a rare, costly loss from one person to a large pool of people who share it through premiums. It works because individual losses are unpredictable while the average across many similar risks is steady. Premiums fund claims, costs and a safety margin. Cover is only offered for risks that are accidental, measurable and outside the insured's control, and always inside the rules of the competent Russian supervisory authority.",
  ["Define risk pooling and the law of large numbers.", "Define premium, sum insured, excess, limit and exclusion.", "Separate insurable risks (accidental, measurable, not controllable) from uninsurable ones.", "Explain insurable interest and utmost good faith.", "Sketch the parties: insured, insurer, intermediary, regulator."],
  "A pool has 1,000 homes. Each faces a 0.2 percent yearly chance of a fire costing 2,000,000 RUB. Step 1: expected losses = 1,000 x 0.002 = 2 fires, or 4,000,000 RUB for the pool. Step 2: per home = 4,000,000 / 1,000 = 4,000 RUB. Step 3: costs and margin take 30 percent of the premium, so premium = 4,000 / 0.70 = 5,714 RUB. Check: 1,000 x 5,714 = 5,714,000 RUB; 70 percent of that is 4,000,000 RUB, which covers the expected claims.",
  "Calculate expected loss and premium for a model pool.", "Expected loss and premium correct to 1 percent."),
 ("Types of cover", "Understand", 4, "Cover differs by what is protected and who is protected. Life and health cover protect people, property and motor cover protect things, and liability cover pays for harm done to others. Some cover is compulsory under the relevant federal rules and some is voluntary. Indemnity cover restores the actual loss, while fixed-benefit cover pays an agreed sum. Reading each type's limits and common exclusions prevents false expectations.",
  ["List life, health, property, motor, travel and liability cover.", "Match cover to risk: property cover to a building, liability to harm to others.", "Explain compulsory versus voluntary cover as set by the relevant federal rules.", "Describe indemnity versus fixed-benefit cover.", "Know the common exclusions: war, wear and tear, intent."],
  "A flat is worth 4,500,000 RUB but insured for 3,000,000 RUB. Step 1: proportion insured = 3,000,000 / 4,500,000 = 0.667, so one third is uninsured. Step 2: a 600,000 RUB loss is paid at 600,000 x 0.667 = 400,000 RUB under the average rule, before any excess. Step 3: the customer bears 200,000 RUB. Check: 400,000 / 600,000 = 0.667, the same proportion as sum insured to value. Advice: raise the sum insured to the true value.",
  "Fill a cover map for a sample family.", "Each risk matched to a cover type with reason."),
 ("Risk assessment and pricing", "Apply", 5, "A premium reflects the chance and size of loss, plus costs and tax. Underwriters start from a base rate for the class of risk, then adjust with loadings where risk is higher and discounts where it is lower. Each factor needs a reason that can be shown to the customer and the supervisor. Pricing must be fair, consistent between similar customers and checked for sense, never set by guesswork or pressure.",
  ["Start from a base rate for the class of risk.", "Apply loadings for age, location, use and claims history.", "Apply discounts for excess, security and no-claim periods.", "Add tax and fees as the rules require.", "Review the result for sense."],
  "Base rate for a motor class is 8,000 RUB. Step 1: city loading 1.25 gives 10,000 RUB. Step 2: young driver loading 1.10 gives 11,000 RUB. Step 3: no-claims discount 0.85 gives 9,350 RUB. Step 4: add any required tax or fee from the rate table. Check: multiply the factors first, 1.25 x 1.10 x 0.85 = 1.16875, and 8,000 x 1.16875 = 9,350 RUB. Both routes agree, and the result is about 17 percent above base, which is sensible.",
  "Price three sample risks with a rate table.", "All three within 1 percent of the model."),
 ("Reading policies", "Analyse", 4, "Words decide who pays. A policy has a schedule naming the insured, period, sum insured and excess, definitions that fix the meaning of terms, cover clauses, exclusions and conditions the customer must meet, such as prompt notice of loss. Reading definitions before cover clauses avoids misreading. A comparison table shows gaps and overlaps, so a recommendation rests on wording and not on headline price.",
  ["Find the schedule, insured, period, sum insured and excess.", "Read definitions before cover clauses.", "Find conditions the customer must meet, such as notice of loss.", "Compare two policies in a table.", "Highlight gaps and overlaps."],
  "Policy A: excess 5,000 RUB, limit 1,500,000 RUB, flood covered, premium 12,000 RUB. Policy B: excess 2,000 RUB, limit 1,000,000 RUB, flood excluded, premium 10,500 RUB. Step 1: premium gap = 1,500 RUB. Step 2: for a flood-prone home with a 900,000 RUB flood loss, A pays 895,000 RUB and B pays 0. Step 3: B saves only 3,000 RUB of excess on other claims. Check: A costs 1,500 RUB more yet protects against the largest loss, so A is better.",
  "Compare two sample policies in a table.", "Table covers limits, excess, exclusions and a recommendation."),
 ("Needs analysis and fair advice", "Create", 4, "Advice starts with the customer, not the product. A needs analysis asks about people, property, income, debts and liabilities, then ranks risks by likelihood and size. The adviser explains cost, limits and exclusions in plain words, states what is not known, and records the reasons for each recommendation. Records are kept for the period the rules require, and advice stays within the authority held.",
  ["Ask about people, property, income and liabilities.", "Record answers and the reasons for a recommendation.", "Explain cost, limits and exclusions in plain words.", "Never mislead; state what you do not know.", "Keep records for the period the rules require."],
  "A family has one earner and a 3,000,000 RUB mortgage. Monthly living costs are 40,000 RUB. Step 1: debt to clear = 3,000,000 RUB. Step 2: two years of costs = 40,000 x 24 = 960,000 RUB. Step 3: life cover needed = 3,000,000 + 960,000 = 3,960,000 RUB. Check: existing savings of 500,000 RUB would reduce the gap to 3,460,000 RUB. Record the figures, the reasons and the customer's decision.",
  "Write a needs analysis for a sample customer.", "Five risk areas covered; reasons recorded."),
 ("Claims handling", "Evaluate", 5, "A claim is a promise tested. Fair and prompt handling rests on evidence and policy wording. The handler logs the notice and its time, collects photos, reports and receipts, checks that cover was active and no exclusion applies, then calculates payment after excess and any average. The decision is written with reasons, and the customer is told how to complain. Never promise payment before checks are done.",
  ["Log the notice and time limits.", "Gather evidence: photos, reports, receipts, statements.", "Check cover, period, excess and exclusions.", "Calculate payment; apply average if under-insured.", "Write reasons, and tell the customer how to complain."],
  "Loss 120,000 RUB, excess 5,000 RUB. Case 1, full cover: 120,000 - 5,000 = 115,000 RUB. Case 2, sum insured is 60 percent of value: step 1, 120,000 x 0.6 = 72,000 RUB; step 2, less excess 5,000 gives 67,000 RUB. Check: the difference between the cases is 48,000 RUB, which equals 40 percent of 120,000, the under-insured share. Write the reasons and calculation in the file before telling the customer.",
  "Process two sample claims with a file each.", "Decision correct with reasons; calculation shown."),
 ("Fraud, ethics and data", "Evaluate", 3, "Fraud raises premiums for everyone and harms honest customers. Handlers learn common red flags such as late notice, inconsistent accounts and missing receipts, but a flag is a reason to look closer, not proof. Cases are escalated to the person in charge, not argued with the customer. Personal data is shared only as needed, conflicts of interest are disclosed, and vulnerable customers get extra care.",
  ["Spot red flags: late notice, inconsistent stories, no receipts.", "Escalate, do not accuse.", "Protect personal data; share only as needed.", "Avoid conflicts of interest; disclose commission where the rules require.", "Treat customers fairly, including vulnerable ones."],
  "A 'stolen laptop' claim of 90,000 RUB arrives 2 days after cover began, with no receipt. Step 1: list flags: new policy, no proof of purchase, high value. Step 2: do not refuse; ask for the serial number, a bank record and the police report. Step 3: escalate to the supervisor within 1 working day. Check: three flags are a pattern to review, not a verdict. Keep notes factual and decide only when the evidence is complete.",
  "Review a case file and list red flags and next steps.", "Flags listed; escalation route stated."),
 ("Compliance and review", "Evaluate", 3, "A licensed business works within the rules and tests itself. Staff must know exactly what authority the licence or employer gives them and stay inside it. Complaint logs show repeating causes to fix. Sample file audits against a checklist reveal gaps before a supervisor does. Measures such as claim handling time in days and complaint rate are tracked, and training is updated when rules or errors change.",
  ["Know what authority the licence or employer gives you.", "Keep complaint logs and fix causes.", "Check files in a sample audit.", "Track key measures: claim time in days, complaint rate.", "Plan training and updates."],
  "Audit 20 claim files against a 10-item checklist. Step 1: count complete files: 17. Step 2: completion rate = 17 / 20 = 85 percent. Step 3: a 95 percent target means at most 1 incomplete file in 20, so the gap is 2 files. Step 4: list the missing items, such as no reasons or no complaint notice, and assign fixes. Check: re-audit 10 new files in 4 weeks; 10 of 10 complete confirms the plan works.",
  "Audit five files against a checklist.", "Results counted and an action plan written.")],
 quiz=[("What is risk pooling?", "Many people pay in so a few losses are shared."),
  ("Define excess.", "The part of a loss the insured pays."),
  ("What is average?", "Reducing a payment when the sum insured is less than the value."),
  ("Expected loss: 0.2 percent x 2,000,000 RUB.", "4,000 RUB."),
  ("Why read definitions first?", "Terms set the meaning of cover."),
  ("Name two red flags of fraud.", "Late notice, missing receipts or inconsistent accounts."),
  ("May you sell insurance without authority?", "No; the competent authority's licence or registration is required."),
  ("What goes into a premium?", "Expected loss, costs, margin and tax."),
  ("Why record advice?", "To show it was suitable and to meet the rules."),
  ("Who do you check legal limits with?", "The competent Russian authority and a local adviser.")],
 rubric=[("Concept accuracy", "Terms confused.", "Terms used correctly.", "Explains with examples."),
  ("Pricing", "Errors above 1 percent.", "Within 1 percent.", "Checks reasonableness."),
  ("Policy analysis", "Misses exclusions.", "Compares limits and exclusions.", "Recommends with reasons."),
  ("Claims decision", "Wrong or no reasons.", "Correct with reasons.", "Handles edge cases fairly."),
  ("Compliance and ethics", "Oversteps authority.", "Stays in authority and records.", "Spots risks and escalates.")],
 ladder=["L1 Basic: name the main types of cover.", "L2 Awareness: explain premium, excess and exclusions.", "L3 Foundation: read a policy and answer customer questions.", "L4 Practitioner: assess needs, price simple risks and process claims under supervision.", "L5 Specialist: handle complex lines or underwriting within authority.", "L6 Advanced: lead a team and design products within the rules.", "L7 Super expert: advise on portfolio, solvency and conduct standards."],
 jobs=[("Insurance agent", "Sells cover within a licence."), ("Claims handler", "Assesses and settles claims."), ("Underwriter assistant", "Prepares risk files."), ("Customer service officer", "Answers policy questions."), ("Compliance assistant", "Checks files and records.")],
 next="Credit and Debit Counselling, Metals and Commodities and Childcare."),

dict(id="RU-20", title="Metals and Commodities", level="L4 Practitioner",
 summary="Learn how metals and other commodities are graded, priced, stored, traded and moved, and how to check quality and risk.",
 outcomes=[("Understand", "Explain grades, assays, weights and delivery terms for common metals."),
  ("Apply", "Calculate the value of a lot from weight, purity and price."),
  ("Analyse", "Compare two supply offers on price, quality, delivery and risk."),
  ("Evaluate", "Judge a document set for gaps and mismatches."),
  ("Create", "Build a buy-store-sell plan with a margin and risk check.")],
 task="Value, compare and document a physical commodity lot from purchase to delivery.",
 condition="In 6 weeks with sample certificates, price tables, a calculator and a spreadsheet.",
 standard="Valuation within 0.5 percent of model; document check finds all planted errors; margin plan sums correctly; pass mark 8 of 10.",
 who="Trainees in trading, procurement, recycling and logistics.",
 req="Arithmetic and spreadsheet basics.",
 safety="Precious metals, scrap, strategic materials and some commodities are regulated: licences, registration, reporting, customs and origin rules apply, and handling can be hazardous (heavy loads, dust, radioactive or toxic scrap). Check with the competent Russian authority and a local adviser before buying, holding, shipping or exporting. This course teaches analysis, not trading advice, and no price outcome is promised.",
 evidence="Evidence: valuation sheet, offer comparison, document check log and a buy-store-sell plan.",
 modules=[
 ("Commodity basics", "Understand", 4, "A commodity is a standard good bought by grade and quantity, not by brand. Ferrous metals are iron-based, non-ferrous metals include copper and aluminium, and precious metals are priced by purity and weight. Quoted units vary: tonne, kilogram and troy ounce. Spot deals deliver soon at today's price, forward deals fix a price for later. Knowing the uses of each commodity explains demand and price swings.",
  ["Define ferrous, non-ferrous, precious and soft commodities.", "Explain grade, purity and tolerance.", "List the quoted units: tonne, kg, troy ounce (31.1035 g).", "Distinguish spot and forward deals.", "Know typical uses to see demand."],
  "A 2.5 kg bar is 99.9 percent pure. Step 1: pure metal = 2.5 x 0.999 = 2.4975 kg = 2,497.5 g. Step 2: troy ounces = 2,497.5 / 31.1035 = 80.3 oz. Check by reverse: 80.3 x 31.1035 = 2,497.6 g, matching within rounding. At a quoted price per gram the value follows from 2,497.5 g, not from the gross 2,500 g, so purity cannot be ignored. Keep three significant digits in the answer.",
  "Convert five weights between kg, g and troy ounces.", "All conversions correct to 3 digits."),
 ("Quality and testing", "Understand", 4, "Quality is checked by sampling and test, not by trust. A sample must be representative, taken from several points of the lot, sealed and labelled so it cannot be changed. Laboratory assay or spectrometer tests give purity and composition. A certificate shows lot, weight, grade, date and laboratory. Moisture and impurity deductions reduce payable weight, and an unbroken chain of custody protects buyer and seller.",
  ["Explain sampling: representative, sealed, labelled.", "Describe assay and spectrometer checks.", "Read a certificate: lot, weight, grade, date, lab.", "Know moisture and impurity deductions.", "Keep chain of custody."],
  "A 20 t lot of scrap shows 4 percent moisture and 2 percent dirt. Step 1: total deduction = 4 + 2 = 6 percent. Step 2: payable weight = 20 x 0.94 = 18.8 t. Step 3: deducted weight = 20 x 0.06 = 1.2 t. Check: 18.8 + 1.2 = 20.0 t. Applying the deductions one after the other gives 20 x 0.96 x 0.98 = 18.82 t, so the contract must state the method; here the additive method pays on 18.8 t.",
  "Apply deductions to three sample lots.", "Net weights correct."),
 ("Pricing and valuation", "Apply", 5, "Value is weight multiplied by purity and price, adjusted for costs and terms. Start from a reference price and add or subtract the agreed premium or discount. Then add freight, insurance and handling to reach delivered cost per tonne. Here all values are in RUB, and currency conversion is added only when a deal needs it. Always check the result against a second price source before relying on it.",
  ["Use a reference price and a premium or discount.", "Convert currency only where the deal needs it; here values are in RUB.", "Add freight, insurance and handling.", "Compute the delivered cost per tonne.", "Check against another source."],
  "Net 18.8 t at 210,000 RUB per tonne. Step 1: metal value = 18.8 x 210,000 = 3,948,000 RUB. Step 2: freight = 18.8 x 7,200 = 135,360 RUB. Step 3: delivered = 3,948,000 + 135,360 = 4,083,360 RUB. Step 4: per tonne = 4,083,360 / 18.8 = 217,200 RUB. Check: 210,000 + 7,200 = 217,200 RUB per tonne, which matches. A second price source within 0.5 percent confirms the reference.",
  "Value two lots to delivered cost.", "Within 0.5 percent of the model."),
 ("Storage and handling", "Apply", 3, "Metal and bulk goods lose value through loss, damage and mix-up. Keep lots segregated by grade, weigh in and out on a scale with a valid calibration, and control moisture, rust and theft. Lifting gear must be used within its rated load by trained operators, because heavy loads cause serious injury. Regular stock counts compare book and physical quantities, and any gap beyond tolerance is investigated.",
  ["Segregate by grade and lot.", "Weigh in and out on a calibrated scale.", "Control moisture, rust and theft.", "Use lifting gear within rated load and trained operators.", "Count stock regularly."],
  "A pile is weighed in at 20,040 kg and out at 19,980 kg with no sales between. Step 1: loss = 20,040 - 19,980 = 60 kg. Step 2: loss rate = 60 / 20,040 = 0.30 percent. Step 3: tolerance of 0.5 percent = 20,040 x 0.005 = 100.2 kg. Check: 60 kg is below 100.2 kg, so no investigation is needed. A loss of 150 kg (0.75 percent) would trigger a review of the scale and access logs. Closing stock equals opening plus in less out.",
  "Fill a stock sheet for a week.", "Opening plus in less out equals closing."),
 ("Contracts and delivery terms", "Analyse", 4, "Terms decide who bears cost and risk at each step. A contract sets the price basis, quantity tolerance, payment timing, delivery point, inspection window and claim period. Ex-works means the buyer arranges and pays transport from the seller's site, while delivered means the seller does. Penalty and force majeure clauses move risk. Use standard clauses where possible and take qualified advice on anything unusual.",
  ["Read price basis, quantity tolerance, payment and delivery point.", "Compare ex-works and delivered terms.", "Check inspection and claims windows.", "Spot penalties and force majeure.", "Use standard clauses; take advice on unusual ones."],
  "Offer A: 205,000 RUB per tonne ex-works plus freight 7,200 RUB per tonne. Offer B: 211,000 RUB per tonne delivered. Step 1: A delivered = 205,000 + 7,200 = 212,200 RUB per tonne. Step 2: difference = 212,200 - 211,000 = 1,200 RUB per tonne. Step 3: on 20 t, B saves 24,000 RUB. Check: B is cheaper, but compare payment days and the claims window too, since a longer credit period may outweigh 1,200 RUB.",
  "Compare two offers in a table.", "Total delivered cost for both; one risk noted each."),
 ("Documents and compliance", "Evaluate", 5, "A lot is only as good as its papers. Mismatches between invoice, packing list, quality certificate and transport papers stop shipments and payments. The checker confirms quantities, grades and dates agree, origin and any required licence or permit exist, and the seller is who they claim to be with authority to sell. Anti-money-laundering checks are recorded as the rules require, and records are kept for the required period.",
  ["Check invoice, packing list, certificate and transport papers agree.", "Verify origin and any required licence or permit.", "Confirm seller identity and authority.", "Record anti-money-laundering checks as the rules require.", "Keep records for the required period."],
  "Invoice states 19.5 t, packing list 19.8 t, weighbridge ticket 19.5 t. Step 1: compare all three; two agree at 19.5 t. Step 2: difference = 19.8 - 19.5 = 0.3 t, or 1.5 percent of 19.5 t. Step 3: at 210,000 RUB per tonne the gap is worth 0.3 x 210,000 = 63,000 RUB. Check: do not pay until the packing list is corrected or explained in writing. Log the finding, the document numbers and who was told.",
  "Audit a set of five documents with planted errors.", "All errors found and listed."),
 ("Risk and margin", "Evaluate", 4, "Price moves, currency changes, credit failures and quality disputes all eat margin. Gross margin is sale minus delivered cost, shown in RUB and as a percentage of cost. Stress tests move the sale price by plus and minus 5 percent to see whether the deal survives. Limit exposure per counterparty, match buying and selling where possible, and count storage days and finance cost before committing.",
  ["Compute gross margin and per-tonne margin.", "Stress price by plus and minus 5 percent.", "Limit exposure per counterparty.", "Use fixed price or matched buying and selling where possible.", "Note storage days and finance cost."],
  "Buy cost 4,083,360 RUB, sell 4,300,000 RUB. Step 1: margin = 216,640 RUB, which is 5.3 percent of cost (216,640 / 4,083,360). Step 2: sell price down 5 percent = 4,085,000 RUB, margin 1,640 RUB. Step 3: down 6 percent = 4,042,000 RUB, a loss of 41,360 RUB. Check: the deal breaks even near a 5.0 percent fall, so a 5.3 percent margin is thin. Require a fixed sale price or a smaller position.",
  "Stress-test a deal at plus and minus 5 percent.", "Three cases computed; decision stated."),
 ("Plan and review", "Create", 3, "A written plan links buying, storing, selling and checking. It sets volumes, timing and limits, lists the checks before each step, names who signs off, and states stop rules for failed quality or document tests. After the deal, results are compared with the plan and lessons are kept. A plan also records the licences, reporting and customs steps that must be confirmed with the competent authority first.",
  ["Set volume, timing and limits.", "List checks before each step.", "Define who signs off.", "Review results against plan.", "Keep lessons learned."],
  "Plan: buy 40 t in two lots of 20 t at 210,000 RUB per tonne, store up to 10 days, sell at a fixed price. Step 1: cost per lot = 20 x 210,000 = 4,200,000 RUB; total 8,400,000 RUB. Step 2: set the exposure limit at 9,000,000 RUB. Step 3: stop rule: if the first lot fails the assay, do not buy the second. Check: 8,400,000 RUB is within the limit, leaving 600,000 RUB for freight and handling.",
  "Write a one-page plan.", "Plan has volumes, checks, sign-offs and stop rules.")],
 quiz=[("How many grams in a troy ounce?", "31.1035 g."),
  ("Net weight: 20 t, 4 percent moisture, 2 percent dirt.", "18.8 t."),
  ("Why seal samples?", "To prove they were not changed."),
  ("What is a spot deal?", "Buying for near-immediate delivery at today's price."),
  ("Which documents must agree?", "Invoice, packing list, certificate and transport papers."),
  ("Why weigh on a calibrated scale?", "To trust weights and settle disputes."),
  ("Compute: 18.8 t x 210,000 RUB.", "3,948,000 RUB."),
  ("Name two risks to margin.", "Price move and quality failure."),
  ("May precious metals be traded freely?", "No; licences and rules apply."),
  ("Who to check rules with?", "The competent Russian authority and a local adviser.")],
 rubric=[("Valuation", "Errors above 0.5 percent.", "Within 0.5 percent.", "Checks with a second source."),
  ("Offer comparison", "Ignores freight.", "Total delivered cost compared.", "Risks priced too."),
  ("Document audit", "Misses errors.", "Finds all planted errors.", "Explains the effect of each."),
  ("Risk analysis", "No stress test.", "Stress test done.", "Limits and stops set."),
  ("Compliance awareness", "Ignores rules.", "Names licences and checks.", "Builds checks into the plan.")],
 ladder=["L1 Basic: name common metals and units.", "L2 Awareness: explain grades and quality checks.", "L3 Foundation: value a lot and read a certificate.", "L4 Practitioner: compare offers, audit documents and plan a deal.", "L5 Specialist: manage a commodity line with risk limits.", "L6 Advanced: lead sourcing and compliance for a business.", "L7 Super expert: advise on market structure, quality systems and regulation."],
 jobs=[("Procurement assistant", "Sources materials."), ("Trading desk trainee", "Supports pricing and records."), ("Quality inspector", "Samples and checks lots."), ("Warehouse controller", "Counts and reconciles stock."), ("Documents clerk", "Checks shipping and trade papers.")],
 next="Insurance, Credit and Debit Counselling and Logistics and Transport."),

dict(id="RU-21", title="Childcare", level="L4 Practitioner",
 summary="Learn to care for children safely and kindly: routines, development, play, health, safeguarding and clear communication with parents.",
 outcomes=[("Understand", "Explain stages of child development from birth to 7 years."),
  ("Apply", "Run a safe daily routine for a small group."),
  ("Analyse", "Identify hazards and rank them by likelihood and harm."),
  ("Evaluate", "Judge whether a child's behaviour or health needs action or referral."),
  ("Create", "Build an activity plan, a record sheet and a parent update.")],
 task="Plan and run a half-day session for a small group and keep proper records.",
 condition="Over 6 weeks, under supervision of a qualified carer, with a checklist, record sheets and play materials.",
 standard="Child to adult ratio kept at or below the limit set by the competent authority; all hazards on a 20-item checklist checked; records complete; pass mark 9 of 10 on safeguarding items.",
 who="Assistants, parents and new carers.",
 req="Minimum age and clearances as set by the competent authority; a supervising qualified carer.",
 safety="Childcare is a regulated field. Working alone with children, running a setting, and giving first aid or medicine require checks, qualifications, licence or registration set by the competent Russian authority and the relevant federal rules. This course does not replace them. If a child is at risk, report to the person in charge and the competent body at once. Do not diagnose illness or give medicine without authority. Check with the competent Russian authority and a local adviser.",
 evidence="Evidence: hazard checklist, daily routine, activity plan, attendance and incident records, and a parent update.",
 modules=[
 ("Child development", "Understand", 4, "Children grow in steps, and knowing the steps shows what is fair to expect at each age. Physical skills, language, social play and thinking develop together but at different speeds for each child. A carer observes and records what a child does in neutral words, without labels, and matches play to the stage reached. Concerns about delay are raised with the supervisor, never diagnosed by the assistant.",
  ["Describe physical, language, social and thinking steps from 0 to 7 years.", "Note that each child differs.", "Observe and record without labels.", "Match play to stage.", "Spot delays to raise with the supervisor."],
  "At 12 months many children use 1 to 3 words; at 24 months about 50. Step 1: a child of 24 months using 10 words is well below 50, a gap of 40 words. Step 2: note the exact words heard, dates and settings over two weeks. Step 3: share the neutral notes with the supervisor. Check: normal growth varies widely, so one low count is not proof of delay. Never diagnose or tell parents a condition.",
  "Observe one child for 10 minutes and record neutral notes.", "Notes factual and dated."),
 ("Safety and hazards", "Analyse", 4, "Most harm to children is preventable. A risk check walks the room and yard looking for hazards before children find them: water, heat, small objects, stairs, doors, plants and chemicals. Each hazard is scored for likelihood and harm, controls such as gates, covers and locked storage are applied, and the score is rechecked. Equipment is inspected daily and fire exits are practised.",
  ["List hazards: water, heat, small objects, stairs, doors, plants, chemicals.", "Rank by likelihood x harm on a 1 to 5 scale.", "Apply controls: gates, covers, storage.", "Check equipment daily.", "Plan fire exit and practice."],
  "Cleaning spray sits on a low shelf. Step 1: likelihood 3 (children reach it daily) x harm 5 (poisoning) = 15, a high score. Step 2: control: move it to a locked cupboard at 150 cm or higher. Step 3: recheck: likelihood falls to 1, harm stays 5, score 5. Check: 15 down to 5 is a two-thirds reduction. Record the date, who moved it and the new score. A residual score above 8 goes to the supervisor.",
  "Complete a 20-item hazard checklist on a room.", "Every item rated and a control listed."),
 ("Ratios and supervision", "Apply", 3, "Enough adults, watching, is the first safety measure. The ratio of adults to children is set by the competent authority for each age and must never be exceeded. Carers count children at every change of place, keep sight lines open, sign children in and out, and never leave a child alone near water or another serious risk. If a carer is absent, the group size must fall.",
  ["Know the ratio for each age set by the competent authority.", "Count children at each change of place.", "Keep sight lines open.", "Never leave a child unattended with water or a risk.", "Sign children in and out."],
  "The limit is 1 adult to 8 children aged 3 to 7. Group sizes: 18, 25, 8 and 9. Step 1: 18 / 8 = 2.25, round up to 3 adults. Step 2: 25 / 8 = 3.125, round up to 4. Step 3: 8 / 8 = 1 adult. Step 4: 9 / 8 = 1.125, round up to 2. Check: 3 adults x 8 = 24 places covers 18, while 2 adults x 8 = 16 would not. Always round up, and plan cover for toilet breaks.",
  "Compute adults needed for four group sizes.", "All correct and rounded up."),
 ("Daily routine and care", "Apply", 5, "A steady day gives children security, and care tasks are part of learning. Plan arrival, play, snack, rest, outdoor time and tidy-up in a fixed order with times. Handwashing before eating and after the toilet, a daily check of the allergy list, private and recorded toilet and nappy care, and rest times suited to age are all part of the routine. Allow slack for slow transitions.",
  ["Plan arrival, play, snack, rest, outdoor time, tidy up.", "Handwashing before eating and after toilet.", "Meals and allergies: check the list daily.", "Toilet and nappy changing with privacy and records.", "Rest times by age."],
  "A 4-hour session: arrival 30 min, free play 60, snack 20, outdoor 60, story 30, activity 40. Step 1: add 30 + 60 = 90; + 20 = 110; + 60 = 170; + 30 = 200; + 40 = 240 minutes. Step 2: 240 / 60 = 4 hours, matching the session. Check: handwashing (5 min) sits inside the arrival and snack blocks, and the allergy list is checked before the 20-minute snack. Outdoor time is 60 / 240 = 25 percent of the session.",
  "Write a timed routine for a half day.", "Times sum to the session; care tasks included."),
 ("Play and learning", "Create", 4, "Play is how children learn, so plans should be simple, safe and flexible. Choose one goal such as language, movement, counting or sharing, prepare age-fit materials without small parts for young children, offer choice and follow the children's interest. Mix quiet and active play and keep adults close. Afterwards record what children actually did, which guides the next plan.",
  ["Choose a goal: language, movement, counting, sharing.", "Prepare materials that are safe and age-fit.", "Offer choice and follow interest.", "Include quiet and active play.", "Record what children did."],
  "Counting game with 10 blocks for children aged 4 to 5; goal: match number to amount up to 10. Step 1: each child gets 10 large blocks (none smaller than 4 cm, to avoid choking). Step 2: sort into groups of 2, then 5, then 10. Step 3: ask 'how many?' and let the child count. Check: 5 groups of 2 = 10 and 2 groups of 5 = 10, so every sort uses all blocks. Allow 15 minutes and record who counted correctly to 10.",
  "Plan two activities with goals.", "Each has goal, materials, steps and safety note."),
 ("Health, first aid and illness", "Evaluate", 4, "Know when to act and who to call. Only trained and authorised people give first aid. Carers learn the signs of illness that need a parent call, limit spread through handwashing and cleaning, record every accident, and tell parents the same day. Medicine is given only with written consent and authority. Serious signs such as breathing trouble, unconsciousness or heavy bleeding mean calling emergency services at once.",
  ["Know signs of illness that need a parent call.", "Handwashing and cleaning to limit spread.", "Record accidents and tell parents.", "Medicine only with written consent and authority.", "Call emergency services for serious signs."],
  "A child has a temperature of 38.5 C and is lethargic at 10:20. Step 1: tell the person in charge at once. Step 2: seat the child quietly apart, with an adult in view. Step 3: call the parent at 10:25 and agree pick-up. Step 4: record times, signs and actions. Check: 38.5 is above the 38 C trigger, so a parent call is required. Do not give medicine or name an illness; call emergency services if breathing is difficult.",
  "Fill an incident form for a sample fall.", "Time, place, injury, action and who told."),
 ("Safeguarding and behaviour", "Evaluate", 4, "Children's safety comes first, and fair, calm guidance builds trust. Carers learn the signs of harm such as unexplained injuries, fear or sudden changes in behaviour. They report to the person in charge and follow the route set by the competent authority, never investigating or promising secrecy. Behaviour is guided with praise, clear limits and redirection, never with harm or shame, and photos and data stay private.",
  ["Recognise signs of harm: injuries, fear, change in behaviour.", "Report to the person in charge and follow the route set by the competent authority.", "Do not investigate yourself or promise secrecy.", "Use praise, clear limits and redirection; never harm or shame.", "Keep photos and data private."],
  "At 14:10 a child says a bruise on the arm came from an adult at home. Step 1: listen calmly and do not ask leading questions. Step 2: write the exact words, the time 14:10, the bruise location and size (about 4 cm) and who was present. Step 3: report to the person in charge before 14:30 and again in writing the same day. Check: record only facts, no opinion, and do not contact the family yourself. Keep the note locked.",
  "Role-play a report and write a safe record.", "Words recorded exactly; report made the same day."),
 ("Working with parents", "Create", 3, "Parents are partners, and clear, kind, timely news builds trust. Greet families, hand over with a short factual note, share good news as well as concerns, and agree contact routes and who may collect each child. Complaints are heard calmly and logged. Respect privacy by sharing information about a child only with that child's parents or those the rules allow, and keep updates short and plain.",
  ["Greet and hand over with a short note.", "Share good news as well as concerns.", "Agree contact routes and pick-up people.", "Handle complaints calmly and log them.", "Respect privacy."],
  "Write a parent update for Mira. Step 1: choose three facts: built a tower of 8 blocks, ate her snack, rested 40 minutes. Step 2: add one request: bring spare socks. Step 3: write it kindly: 'Today Mira built a tower of 8 blocks, ate her snack and rested 40 minutes. Please bring spare socks tomorrow.' Check: 20 words, under the 60-word limit, all facts observed, no labels and no other child named.",
  "Write three parent updates.", "Each is factual, kind and under 60 words.")],
 quiz=[("Why record observations without labels?", "To stay factual and fair."),
  ("Hazard score for likelihood 3 and harm 5?", "15."),
  ("Adults needed for 18 children at 1 to 8?", "3."),
  ("Who gives medicine?", "Only authorised staff with written consent."),
  ("What do you do if a child discloses harm?", "Listen, record exact words, report the same day."),
  ("Why count children at changes of place?", "To catch missing children at once."),
  ("Where store cleaning products?", "Locked and out of reach."),
  ("How long is a 240-minute session in hours?", "4 hours."),
  ("Can you promise a child secrecy?", "No."),
  ("Who sets ratios and registration?", "The competent Russian authority.")],
 rubric=[("Safety and hazards", "Hazards missed.", "All checklist items rated.", "Controls improve the room."),
  ("Routine and care", "Routine vague.", "Timed routine with care tasks.", "Adapts to children's needs."),
  ("Play planning", "No goal.", "Goal, materials and steps.", "Follows child interest."),
  ("Safeguarding", "Unsure how to report.", "Correct record and route.", "Handles with calm and care."),
  ("Communication", "Unclear or unkind.", "Clear and factual updates.", "Builds trust with parents.")],
 ladder=["L1 Basic: follow simple safety rules around children with supervision.", "L2 Awareness: explain development steps and hazards.", "L3 Foundation: help with routines and play under supervision.", "L4 Practitioner: plan and run a session with records.", "L5 Specialist: lead a room or a special need approach with authority.", "L6 Advanced: manage a setting within the rules.", "L7 Super expert: advise on practice standards and training."],
 jobs=[("Childcare assistant", "Supports a lead carer."), ("Nursery helper", "Prepares play and meals."), ("After-school club worker", "Runs activities."), ("Nanny", "Cares for a family's children."), ("Play leader", "Plans group play.")],
 next="Petcare Services, Insurance and Art."),

dict(id="RU-22", title="Ceramic Studios", level="L4 Practitioner",
 summary="Learn to make, dry, fire and glaze pots safely, run a small studio, cost work and sell it.",
 outcomes=[("Understand", "Explain clay body, shrinkage, drying and firing stages."),
  ("Apply", "Throw or hand-build six pieces and fire them to a set schedule."),
  ("Analyse", "Calculate shrinkage, clay use and firing cost."),
  ("Evaluate", "Judge pieces for faults and cause."),
  ("Create", "Build a studio plan with safety, costing and a sales range.")],
 task="Make, fire and finish six pieces and cost a small production run.",
 condition="Over 8 weeks in a studio with clay, a wheel or hand-building tools, glazes and a kiln under supervision.",
 standard="Six sound pieces; shrinkage measured within 1 percent; firing log complete; costing adds up; pass mark 8 of 10.",
 who="Hobbyists and starting studio owners.",
 req="Access to a studio and supervised kiln.",
 safety="Clay dust (silica), glaze chemicals and kilns are hazardous: use wet cleaning, respirators where needed, ventilation, heat gloves, and keep flammables away. Only trained people load and fire a kiln. Food-contact ware needs glazes that are safe for it; check with the competent Russian authority and a local adviser about product safety, electrical and fire rules and sale. Do not claim glazes are food safe without proof.",
 evidence="Evidence: six pieces, a shrinkage test tile, a firing log, a glaze record and a costing sheet.",
 modules=[
 ("Clay and tools", "Understand", 4, "Clay bodies differ in texture, plasticity and firing range, and the body you choose decides which glazes, temperatures and forming methods will work. Earthenware is open and forgiving, stoneware dense and strong, porcelain fine but prone to slumping. Moisture, air pockets and mixed batches cause most early failures, so learn to test, wedge, store and label clay before you make anything.",
  ["Compare earthenware, stoneware and porcelain by firing temperature.", "Know grog and its effect on strength.", "Wedge to remove air.", "Keep clay damp and sealed.", "Set up tools and a clean station."],
  "Task: pick a clay for a 1240 C firing. Step 1: stoneware fires about 1200 to 1280 C, so 1240 C is inside its range; earthenware (about 1000 to 1100 C) would slump or bloat. Step 2: a 10 kg bag costs 1,500 RUB, so 1,500 / 10 = 150 RUB per kg. Step 3: a 350 g mug uses 0.35 x 150 = 52.5 RUB of clay. Check: 52.5 / 0.35 = 150, which matches the bag price. A stoneware glaze fired at 1000 C would stay unmelted.",
  "Test three clays and note feel and firing range.", "Notes complete and station clean."),
 ("Forming", "Apply", 5, "Even walls make strong pots, and the forming method should suit the shape: throwing for round symmetrical forms, coiling and pinching for irregular ones, slabs for flat or boxy work. Uneven thickness dries and shrinks unevenly, which cracks ware in the kiln. Learn to centre, check thickness with a needle gauge, score and slip every join, and compress bases to prevent cracks.",
  ["Throw: centre, open, pull, shape.", "Hand-build: pinch, coil, slab.", "Keep wall thickness 5 to 8 mm.", "Score and slip joins.", "Cut a base with a wire."],
  "Task: buy clay for six mugs, each 9 cm tall, 8 cm wide with 6 mm walls, about 350 g thrown. Step 1: 6 x 350 g = 2,100 g = 2.1 kg. Step 2: add 15 percent for trimmings and test pieces: 2.1 x 1.15 = 2.4 kg, so buy one 2.5 kg block. Step 3: at 150 RUB per kg the clay costs 2.5 x 150 = 375 RUB. Check: 375 / 6 = 62.5 RUB per mug, close to the 52.5 RUB bare clay cost plus waste.",
  "Make six pieces in one form.", "Even walls within 2 mm; joins sealed."),
 ("Drying and shrinkage", "Analyse", 4, "Water leaves clay from the surface first, so thin rims and edges dry before thick bases and handles, and the difference pulls a piece apart as cracks. Slow, even drying under loose plastic, away from draughts and heaters, keeps moisture balanced. Shrinkage is the other half: clay shrinks as it dries and again as it fires, so every wet size must be planned from the finished size wanted.",
  ["Dry slowly under loose plastic, then open air.", "Know leather-hard and bone-dry stages.", "Measure shrinkage with a test tile.", "Plan a bigger wet size.", "Dry thick parts longest."],
  "Task: size a mug to fire at 9 cm. Step 1: a 10 cm line on a test tile measures 8.7 cm after firing, so shrinkage = (10 - 8.7) / 10 = 13 percent. Step 2: fired size is 87 percent of wet size, so wet height = 9 / 0.87 = 10.3 cm. Step 3: for an 8 cm width, 8 / 0.87 = 9.2 cm. Check: 10.3 x 0.87 = 8.96 cm and 9.2 x 0.87 = 8.0 cm, within 1 percent of the targets.",
  "Make and measure a 10 cm test tile.", "Shrinkage computed within 1 percent."),
 ("Bisque firing", "Apply", 4, "The first firing turns dry clay into hard, porous ceramic by driving out water and burning off organic matter. Trapped water turns to steam near 100 C and chemically bound water leaves around 500 to 600 C, so ware must be bone-dry and heated slowly through those zones or it can burst and damage other pieces. Stack ware without touching, log every firing, and cool with the kiln closed.",
  ["Make sure ware is bone-dry.", "Stack without touching.", "Follow a schedule: slow to 600 C, then faster to 950 C.", "Log start, peak and time.", "Cool closed until below 100 C."],
  "Task: plan a bisque to 950 C. Step 1: ramp at 100 C per hour from 0 to 600 C: 600 / 100 = 6 hours. Step 2: ramp at 150 C per hour from 600 to 950 C: 350 / 150 = 2.3 hours. Step 3: total heating 8.3 hours, then about 12 hours cooling until below 100 C. Step 4: at 30 kWh per firing and 6 RUB per kWh, energy costs 180 RUB. Check: 6 + 2.3 = 8.3 and 30 x 6 = 180, so schedule and cost agree.",
  "Plan and log a bisque firing.", "Schedule and log completed."),
 ("Glazes", "Apply", 4, "Glaze is a thin layer of glass fused onto clay, and the result depends on recipe, thickness and peak temperature. Too thin looks dry and rough, too thick runs onto the shelf or crawls. Test every new glaze on tiles before your pieces, record the recipe and thickness, and keep glaze chemicals labelled. Never state that ware is food safe without proper proof of testing.",
  ["Dip or brush evenly.", "Wipe the foot clean.", "Test on tiles first.", "Record recipe, thickness and result.", "Wear protection; do not eat from ware without safety proof."],
  "Task: glaze 12 mugs. Step 1: a dip in glaze at 1.4 specific gravity gives a coat of about 0.5 mm; too thick runs on the shelf. Step 2: each mug takes about 40 g of dry glaze, so 12 x 40 = 480 g. Step 3: one 1 kg batch at 400 RUB covers it, costing 480 / 1000 x 400 = 192 RUB, or 16 RUB per mug. Check: 480 g is below 1,000 g, and 192 / 12 = 16 RUB. Fire a test tile first.",
  "Glaze three test tiles and your pieces.", "Even coat; feet wiped; record kept."),
 ("Glaze firing and faults", "Evaluate", 5, "The glaze firing melts the coating to glass at the glaze's peak temperature, often with a short hold to smooth it. Faults are information: crawling points to dust or a thick coat, pinholes to escaping gas, crazing to a body and glaze that shrink differently, warping to uneven walls or fast heating. Keep a fault log linking each defect to a cause and one change to test.",
  ["Fire to the glaze cone; log peak.", "Find causes: crawling (dust or thick coat), pinholes, crazing, warping.", "Fix by changing prep, thickness or schedule.", "Do not open the kiln hot.", "Check shelves are wadded."],
  "Task: diagnose a firing. Result: 4 of 6 mugs show crazing and 1 of 6 shows pinholes. Step 1: crazing rate = 4 / 6 = 67 percent, pinholes = 1 / 6 = 17 percent. Step 2: crazing on most pieces suggests glaze and body shrink differently, so try slower cooling or a different glaze. Step 3: change one thing and refire one tile. Check: if no mug has both faults, 4 + 1 = 5 faulty and 1 sound of 6, matching the log.",
  "Write a fault report for your firing.", "Each fault has cause and fix."),
 ("Studio safety and care", "Evaluate", 3, "Fine silica dust and heat are the two main studio hazards, and both are controlled by housekeeping and habits. Dry sweeping lifts invisible dust that damages lungs over years, so use wet cleaning and a respirator for mixing. Kilns need ventilation, clearance from walls and heat gloves. Keep glaze chemicals labelled and stored safely, and know where the fire extinguisher and first aid kit are.",
  ["Wet-mop; never dry sweep.", "Ventilate the kiln room.", "Keep a safe distance from hot surfaces.", "Store chemicals labelled.", "Plan fire and first aid."],
  "Task: check a kiln room. Step 1: room 2.4 m x 2.0 m x 2.5 m = 12 m3. Step 2: if the maker requires 10 air changes per hour, extraction must move 12 x 10 = 120 m3 per hour; use the maker's own figure. Step 3: a 6 kW kiln at 230 V draws 6,000 / 230 = 26 A, so a qualified electrician must confirm the supply. Check: 26 x 230 = 5,980 W, about 6 kW; keep 30 cm clearance from walls as the maker states.",
  "Complete a studio safety checklist.", "All items checked; actions listed."),
 ("Costing and selling", "Create", 4, "A fair price covers every cost: clay, glaze, kiln energy, your hours, space, packaging and breakage, not only materials. Hours are usually the largest cost of handmade ware. Divide each firing's cost by the pieces in the load, allow for pieces lost to faults, and add a margin for tools and growth. Test the price with a small range, and follow the rules on sale and taxes.",
  ["Add clay per piece, glaze, firing share, hours and space.", "Divide firing cost by pieces per load.", "Add a margin.", "Test market with a small range.", "Follow rules on sale and taxes."],
  "Task: price one mug. Step 1: kiln share: 30 kWh x 6 RUB = 180 RUB per firing; two firings = 360 RUB over 30 mugs = 12 RUB each. Step 2: clay 0.35 kg x 150 = 52.5 RUB; glaze 20 RUB. Step 3: 1.5 hours at 500 RUB = 750 RUB. Step 4: cost = 12 + 52.5 + 20 + 750 = 834.5 RUB; with a 30 percent margin 834.5 x 1.3 = 1,085, so price 1,100 RUB. Check: 1,100 - 834.5 = 265.5 RUB, about 32 percent over cost.",
  "Cost one product and set a price.", "Cost adds up; price includes margin.")],
 quiz=[("Typical stoneware firing range?", "About 1200 to 1280 C."),
  ("Why wedge clay?", "To remove air and even the texture."),
  ("Shrinkage of 10 cm to 8.7 cm?", "13 percent."),
  ("Why dry ware slowly?", "To prevent cracks."),
  ("Why wipe glaze from the foot?", "So the ware does not stick to the shelf."),
  ("What is bisque?", "First firing that hardens the clay."),
  ("How should you clean the floor?", "Wet mop; never dry sweep."),
  ("Cause of crazing?", "Glaze and body shrink differently."),
  ("Who loads the kiln?", "Only trained people."),
  ("May you call ware food safe without proof?", "No.")],
 rubric=[("Forming quality", "Uneven or leaking.", "Even and sound.", "Refined and consistent."),
  ("Measurement", "Shrinkage not measured.", "Computed within 1 percent.", "Used to size new work."),
  ("Firing record", "No log.", "Complete log.", "Log guides improvements."),
  ("Fault analysis", "No causes.", "Causes and fixes listed.", "Tests a fix."),
  ("Safety and costing", "Unsafe habits.", "Safe and costing adds up.", "Plans a studio run.")],
 ladder=["L1 Basic: pinch a simple pot with help.", "L2 Awareness: explain firing stages.", "L3 Foundation: make and glaze a piece.", "L4 Practitioner: produce a small range and cost it.", "L5 Specialist: develop glazes and manage kiln schedules.", "L6 Advanced: run a studio and train others.", "L7 Super expert: advise on materials, safety and production."],
 jobs=[("Studio potter", "Makes and sells ware."), ("Kiln technician", "Loads and fires kilns."), ("Ceramics teacher", "Runs classes."), ("Glaze technician", "Tests and records glazes."), ("Studio manager", "Runs booking and supplies.")],
 next="Art, Furniture (design, make, retail) and Marketing for Makers."),

dict(id="RU-23", title="Credit and Debit Counselling", level="L4 Practitioner",
 summary="Learn to help people understand their money, read credit and debt, build a budget and plan repayment, while staying within the rules and one's authority.",
 outcomes=[("Understand", "Explain interest, repayment schedules, fees and the effect of debt on a household."),
  ("Apply", "Build a monthly budget and a debt list from a client's papers."),
  ("Analyse", "Compare repayment options by total cost and time."),
  ("Evaluate", "Judge when to refer a client to a licensed professional or the competent body."),
  ("Create", "Build a clear action plan and a record of the session.")],
 task="Run a structured money-counselling session and produce a budget, debt list and action plan.",
 condition="In 6 weeks, with sample client files, a calculator, a spreadsheet and a session record template.",
 standard="Budget balances to 0 RUB; interest and payoff calculations within 1 percent; plan has dated steps; referral rule applied correctly; pass mark 8 of 10.",
 who="Money advisers, social workers and bank or community staff in training.",
 req="Arithmetic and spreadsheet basics; respect for privacy.",
 safety="Financial counselling and debt work are regulated in part. Giving credit advice, handling client money, negotiating with creditors or advising on insolvency may need a licence or registration under the relevant federal rules from the competent Russian authority; this course does not grant one. Do not promise debt will be cancelled and do not take fees for outcomes you cannot deliver. Protect personal data. Refer legal and insolvency questions to a qualified lawyer. Check with the competent Russian authority and a local adviser.",
 evidence="Evidence: budget, debt list, payoff comparison, action plan and session record.",
 modules=[
 ("Money and credit basics", "Understand", 4, "Credit is the use of someone else's money now in return for paying more later. Clients often know the instalment but not the full cost, which includes interest, fees and insurance. Learn the terms principal, rate, term, instalment and fee, and the difference between secured debt, backed by an item, and unsecured debt. Explain every figure in plain words before comparing options.",
  ["Define principal, interest rate, term, instalment and fee.", "Separate nominal rate from the full cost.", "Know secured and unsecured debt.", "Describe overdrafts, cards, loans and instalment plans.", "Explain credit history in plain words."],
  "Task: find the cost of a 120,000 RUB loan at 18 percent a year over 12 months. Step 1: monthly rate = 18 / 12 = 1.5 percent. Step 2: instalment = 120,000 x 0.015 / (1 - 1.015^-12) = about 11,000 RUB. Step 3: total paid = 11,000 x 12 = 132,000 RUB, so the cost of credit is 12,000 RUB. Check: 12,000 is 10 percent of the principal, plausible for 18 percent a year on a balance that falls to zero (average about 55 percent: 0.18 x 0.55 = 9.9 percent).",
  "Calculate the instalment and cost of three loans.", "Within 1 percent of the model."),
 ("Interviewing and ethics", "Apply", 4, "A client tells the truth when they feel safe, so the first minutes matter more than any calculation. State your purpose, how data is kept and what you cannot do, then ask open questions and listen. Record facts, not judgments, and never pressure the client or promise results. Shame about debt is common; a calm, respectful manner brings out the full picture of debts and income.",
  ["Open with purpose, privacy and limits of your role.", "Ask open questions and listen.", "Record facts, not judgments.", "Explain what you cannot do.", "Never pressure or promise results."],
  "Opening line: 'I can help you list your money and options. I cannot cancel debts or give legal advice.' Step 1: ask for monthly income and note 60,000 RUB. Step 2: ask for papers on every debt and note a card of 40,000 RUB and a loan of 80,000 RUB. Step 3: read the figures back and ask the client to confirm. Check: 40,000 + 80,000 = 120,000 RUB matches the papers, and the record shows facts only, with role limits and privacy stated.",
  "Role-play an opening and record it.", "Role limits stated; privacy covered."),
 ("Budgeting", "Apply", 5, "A budget compares what comes in with what must go out, and shows what remains after needs. Build it from papers, not memory: pay slips, bank statements, bills and loan schedules. List income by source and date, then essentials, then debt payments, then other spending. Irregular costs such as annual fees should be divided by twelve. Test the plan over three months before trusting it.",
  ["List income by source and date.", "List essentials: rent, food, transport, utilities.", "List debt payments.", "Find the surplus or deficit.", "Test the plan over three months."],
  "Task: balance a monthly budget with income of 60,000 RUB. Step 1: essentials: rent 22,000 + food 15,000 + transport 4,000 + utilities 5,000 = 46,000 RUB. Step 2: add debt payments of 10,000 RUB: spending 56,000 RUB. Step 3: surplus = 60,000 - 56,000 = 4,000 RUB. Step 4: stress case: income down 10 percent to 54,000 RUB gives -2,000 RUB, so a cut is needed. Check: 56,000 + 4,000 = 60,000, so the budget balances to 0 RUB.",
  "Build a balanced budget from a sample file.", "Budget balances to 0 RUB."),
 ("Debt list and priorities", "Analyse", 4, "Not all debts are equal. Priority debts carry the worst consequences if unpaid, such as housing, utilities and secured items, and they come first. Among the rest, rank by interest rate, then balance. Build a list with creditor, balance, rate, instalment and arrears, check for double fees or errors, and keep every letter and statement in order, because dates and papers are the evidence.",
  ["List each debt: creditor, balance, rate, instalment, arrears.", "Mark priority debts: housing, utilities, secured items.", "Rank others by rate.", "Check for double fees or errors.", "Keep every letter."],
  "Task: choose where extra money goes. Debts: card 40,000 RUB at 36 percent a year, loan 80,000 RUB at 15 percent. Step 1: card interest = 40,000 x 0.36 = 14,400 RUB a year. Step 2: loan interest = 80,000 x 0.15 = 12,000 RUB. Step 3: the card costs more on half the balance, so extra money goes first to the card while the loan gets its normal instalment. Check: 14,400 / 40,000 = 36 percent and 12,000 / 80,000 = 15 percent, matching the stated rates.",
  "Build a ranked debt list.", "Fields complete; ranking explained."),
 ("Repayment options", "Analyse", 4, "Repayment options differ in time and total cost. Paying only the minimum is slowest and dearest; a fixed higher amount shortens the term; the snowball method clears small balances first for motivation, while the avalanche method clears the highest rate first to save most interest. Always compute months to payoff and total interest, and beware of restructures that lower the instalment only by lengthening the term and adding fees.",
  ["Compare paying minimum, fixed amount, snowball and avalanche.", "Compute months to payoff.", "Compute total interest.", "Check whether a restructure lowers cost.", "Beware of fees and longer terms."],
  "Task: payoff of 40,000 RUB at 3 percent a month, paying 4,000 RUB monthly. Step 1: first month interest = 40,000 x 0.03 = 1,200 RUB, so 2,800 RUB reduces the balance. Step 2: months = -ln(1 - 1,200 / 4,000) / ln(1.03) = 0.357 / 0.0296 = about 12.1. Step 3: total paid about 12.1 x 4,000 = 48,300 RUB, so interest is about 8,300 RUB. Check: after 12 payments about 260 RUB remains, so the thirteenth payment is small.",
  "Compare two options for a sample debt.", "Months and interest computed within 1 percent."),
 ("Working with creditors", "Create", 4, "Clear, written, factual contact with creditors helps the client and protects the adviser. A short letter states the balance, what the client can pay, from what date, and asks for written confirmation. Keep copies and dates of everything. Negotiate only with the client's written consent and only within your authority; where the matter needs a licence or a lawyer, escalate. Never promise outcomes you do not control.",
  ["Write a short letter with facts and an offer.", "Keep copies and dates.", "Know what you may do under your authority.", "Do not negotiate without client consent.", "Escalate to a licensed professional where needed."],
  "Task: offer a payment plan on a 40,000 RUB balance when the budget surplus is 4,000 RUB. Step 1: offer 3,000 RUB a month, leaving 1,000 RUB reserve. Step 2: months to clear = 40,000 / 3,000 = 13.3, so 14 payments, ignoring added interest. Step 3: letter: 'Balance 40,000 RUB. I can pay 3,000 RUB each month from 5 December. Please confirm in writing.' Check: 14 x 3,000 = 42,000 RUB covers the balance, and 3,000 is below the 4,000 surplus, so the offer is affordable.",
  "Draft a creditor letter.", "Facts, offer, date and request to confirm."),
 ("Referral and the rules", "Evaluate", 4, "Knowing the edge of your role protects the client. Refer legal, insolvency and court matters to a qualified lawyer, distress to proper support, and work that needs a licence to people who hold it. Learn to spot predatory offers and scams, especially promises to cancel debt for an upfront payment. Check licence needs with the competent authority, record the referral and its date, and explain to the client why you are referring.",
  ["Refer legal, insolvency and court matters.", "Refer mental distress to appropriate support.", "Spot predatory offers and scams.", "Never take payment for promised cancellation.", "Check licence needs with the competent authority."],
  "Task: triage a court claim of 300,000 RUB against a client earning 60,000 RUB a month. Step 1: copy the date on the claim and any reply deadline in the papers. Step 2: this is a court matter outside advice limits, so refer to a qualified lawyer the same day. Step 3: list income and debts to hand to the lawyer. Check: 300,000 / 60,000 = 5 months of income, so urgency is high; the record shows the referral, its date and the reason.",
  "Sort ten cases into advise, refer or decline.", "Nine of ten sorted correctly."),
 ("Action plan and follow-up", "Create", 3, "A plan is a short list of dated steps the client can actually do, usually three to five. Each step has an owner and a date, the first step is small and soon, and a check-in is set. Use the budget surplus to size payments, and name what to do if income falls. Record the client's agreement and store records safely under the personal data rules.",
  ["Write three to five steps.", "Give each a date and an owner.", "Set a check-in.", "Record agreement.", "Store records safely."],
  "Task: write a plan for a client with a 4,000 RUB monthly surplus. Step 1: by 10 Dec client and adviser send letters to creditors. Step 2: by 15 Dec client sets a pay-day transfer of 4,000 RUB, with 3,000 RUB to the card and 1,000 RUB to a reserve. Step 3: by 5 Jan review the budget. Check: 3,000 + 1,000 = 4,000 RUB equals the surplus, each step has an owner and a date, and a 40,000 RUB card clears in about 14 months.",
  "Write an action plan for a sample client.", "Steps dated and measurable.")],
 quiz=[("Instalment for 120,000 RUB over 12 months at 18 percent?", "About 11,000 RUB."),
  ("Which debts come first?", "Those with the worst consequence, such as housing."),
  ("Budget: 60,000 income, 56,000 spending.", "4,000 RUB surplus."),
  ("May you promise debt cancellation?", "No."),
  ("Why record facts, not judgments?", "To keep an accurate, fair file."),
  ("When do you refer?", "Legal, insolvency, court or distress matters."),
  ("Avalanche method means?", "Pay the highest-rate debt first."),
  ("Why write to creditors?", "To keep a dated record."),
  ("What data rule applies?", "Protect personal data under the relevant federal rules."),
  ("Who sets licence needs?", "The competent Russian authority.")],
 rubric=[("Calculation", "Errors above 1 percent.", "Within 1 percent.", "Checks totals two ways."),
  ("Budget", "Does not balance.", "Balances to 0 RUB.", "Tests stress cases."),
  ("Client care", "Pressure or judgment.", "Respectful and clear.", "Builds trust and agency."),
  ("Referral", "Oversteps role.", "Refers correctly.", "Explains why to the client."),
  ("Action plan", "Vague.", "Dated steps.", "Includes review and contingency.")],
 ladder=["L1 Basic: explain what interest is.", "L2 Awareness: read a loan statement.", "L3 Foundation: build a simple budget.", "L4 Practitioner: run a session with a debt list and plan.", "L5 Specialist: handle complex cases within a licence.", "L6 Advanced: lead a service and train advisers.", "L7 Super expert: design programmes and advise on policy."],
 jobs=[("Money adviser", "Counsels households."), ("Community finance worker", "Runs workshops."), ("Collections liaison", "Agrees fair plans."), ("Bank customer officer", "Explains products."), ("Social worker aide", "Supports clients with money matters.")],
 next="Insurance, Metals and Commodities and Childcare."),

dict(id="RU-24", title="Petcare Services", level="L4 Practitioner",
 summary="Learn to care for pets safely as a sitter, walker or groomer: handling, feeding, health signs, safety, records and running a small service.",
 outcomes=[("Understand", "Explain basic needs of dogs and cats: food, water, exercise, rest and health checks."),
  ("Apply", "Run a safe visit or walk with a care record."),
  ("Analyse", "Identify risk to the animal, to people and to your business."),
  ("Evaluate", "Judge when a pet needs a vet."),
  ("Create", "Build a service plan, a contract and a price list.")],
 task="Plan and run care for a pet for a day with records, and cost the service.",
 condition="Over 6 weeks, with consenting owners and animals, handling gear, a first aid kit for animals and a record sheet.",
 standard="All visits logged with times and feeding; hazards checked on a 15-item list; price covers costs; pass mark 8 of 10 with all health-escalation items right.",
 who="Pet lovers starting as sitters, walkers or groomers.",
 req="Comfort with animals; written owner consent; proof of identity for clients.",
 safety="Animals can bite, scratch and carry disease. Do not treat, medicate or diagnose; only a licensed vet may do so. Boarding, breeding, selling and transport of animals may need registration or permits under the relevant federal and local rules; check with the competent Russian authority and a local adviser. Follow vaccination and animal welfare rules. Keep your own tetanus and similar cover as advised by a doctor. Insurance for the business is wise.",
 evidence="Evidence: client intake form, care record, hazard checklist, contract and price list.",
 modules=[
 ("Animal needs", "Understand", 4, "A healthy pet has food, clean water, movement, rest, company and a clean space every day. Dogs need regular exercise and toileting; cats need clean litter, perches, hiding places and quiet. Food is set by weight, age and the owner's plan, and is never changed suddenly. Learn normal behaviour, appetite and toileting so that any change stands out early.",
  ["Dogs need daily exercise and toileting 3 to 5 times a day.", "Cats need clean litter, perches and quiet.", "Water must be fresh and always available.", "Food by weight and age; follow the owner's plan.", "Know normal behaviour so change stands out."],
  "Task: portion food for a 10 kg dog on the owner's plan of 25 g dry food per kg per day. Step 1: 10 x 25 = 250 g a day. Step 2: split into two meals of 125 g. Step 3: a 3 kg bag at 600 RUB lasts 3,000 / 250 = 12 days, costing 50 RUB a day. Check: 2 x 125 = 250 g, and 12 days x 50 RUB = 600 RUB, matching the bag price. Keep fresh water out and follow the owner's written plan.",
  "Write a daily care plan for a sample dog and cat.", "Plan lists food, water, exercise and rest."),
 ("Handling and body language", "Apply", 4, "Calm, clear handling keeps you and the animal safe. Dogs and cats show stress before they bite: stiff body, raised hackles, low tail, ears back, lip licking, a turned head. Approach slowly and from the side, use a well-fitted lead and harness, and stop when the animal is stressed. Never separate fighting animals with bare hands, and keep your distance from unknown animals.",
  ["Read signals: stiff body, raised hackles, tail low, ears back.", "Approach slowly and from the side.", "Use a lead and harness properly.", "Never separate fighting animals with bare hands.", "Stop if the animal is stressed."],
  "Task: plan a safe passing distance on a 1.5 m lead. Step 1: keep at least 2 m between your dog and an unknown dog, shorten the lead to 1 m and stand on the far side of your dog. Step 2: if the other dog shows warning signs, cross the street, adding about 6 m of gap. Step 3: at 4.5 km per hour you walk 75 m per minute. Check: 4,500 / 60 = 75 m per minute, so 6 m takes under 5 seconds, a small delay for a large safety gain.",
  "Practise leading and a calm greeting with a supervised dog.", "No pulling or panic; signals named."),
 ("Intake and contract", "Create", 3, "Good information at the start prevents trouble later. Collect owner contact, named vet, diet, medicines, fears, bite history, vaccinations and key access, and ask for written consent for emergency vet care. Agree visit times, fees and cancellation in a short contract. Keep personal data private and locked. Check proof of identity for new clients, and never accept a pet you cannot handle safely.",
  ["Collect owner contact, vet, diet, medicines, fears and key access.", "Record vaccinations and any history of bites.", "Agree times, fees and cancellation.", "Get written consent for emergency vet care.", "Keep data private."],
  "Task: price a one-week contract. Terms: 2 visits a day of 30 minutes, 900 RUB per visit, consent to call the named vet. Step 1: visits = 2 x 7 = 14. Step 2: fee = 14 x 900 = 12,600 RUB. Step 3: cancellation with less than 24 hours notice costs half a visit, 450 RUB. Step 4: the owner sets an emergency vet limit of 5,000 RUB in writing. Check: 12,600 / 14 = 900 RUB per visit, and the contract lists dates, fee, vet, consent clause and signature.",
  "Draft an intake form and contract.", "Fields complete; consent clause included."),
 ("Walks and visits", "Apply", 5, "A structured visit gives safe, useful care. On arrival check the pet's eyes, gait and appetite, then walk a safe route with bags and water. Never leave a pet in a hot car or tied up alone, and lock doors and gates behind you. Shorten walks in heat and ice, and avoid busy roads. Log the time, toileting, food eaten and anything unusual for the owner.",
  ["Check the pet on arrival: eyes, gait, appetite.", "Walk a safe route; carry bags and water.", "Never leave a pet in a hot car or tied up.", "Lock doors and gates behind you.", "Log time, toileting and food eaten."],
  "Task: plan a walk distance. Step 1: 45 minutes at 4.5 km per hour = 0.75 x 4.5 = 3.4 km. Step 2: in 30 C weather cut to 20 minutes in shade: 20 / 60 x 4.5 = 1.5 km. Step 3: test the pavement; if you cannot hold the back of your hand on it for 5 seconds, it is too hot for paws. Check: 1.5 km is less than half of 3.4 km, and the log records start time, route, toileting, water and weather.",
  "Run and log a walk or visit.", "Log has times, food and notes."),
 ("Grooming and hygiene", "Apply", 4, "Grooming prevents matting and skin problems and lets you spot lumps, parasites and sore ears early. Brush by coat type, bathe in lukewarm water with pet shampoo, never human products, and dry thoroughly. Trim nails only if trained, because cutting the quick causes pain and bleeding. Clean tools between animals to stop infection spreading, and stop if the animal is distressed or aggressive.",
  ["Brush by coat type.", "Bathe with pet shampoo, never human products.", "Trim nails only if trained.", "Check ears, teeth, skin for signs.", "Clean tools between animals."],
  "Task: plan coat care for a long-coated dog. Step 1: brushing 10 minutes daily = 70 minutes a week. Step 2: a bath every 4 to 6 weeks means 9 to 13 baths a year (52 / 6 = 8.7 and 52 / 4 = 13), in lukewarm water. Step 3: a 250 ml bottle of pet shampoo at 300 RUB gives 10 baths at 25 ml, so 30 RUB a bath. Check: 250 / 25 = 10 and 300 / 10 = 30 RUB; findings on ears, teeth and skin are noted for the owner.",
  "Groom a supervised animal and record findings.", "No injuries; findings noted."),
 ("Health signs and first aid", "Evaluate", 4, "You are not a vet. Your job is to notice, record and call. Learn the red flags: repeated vomiting, a bloated belly, blood, seizures, heat stress, difficulty breathing and collapse. For any red flag, call the owner and the named vet at once, keep the pet cool, calm and still, and give no human medicine. Write down what you saw and the time so the vet gets clear facts.",
  ["Know red flags: vomiting more than twice, bloated belly, blood, seizures, heat stress, difficulty breathing.", "Call the owner and vet at once for red flags.", "Keep the pet cool, calm and still.", "Do not give human medicine.", "Record what you saw and when."],
  "Task: act on heat stress. A dog is panting hard, drooling and weak after a 30-minute walk in 32 C. Step 1: move to shade at once and note the time, 15:10. Step 2: offer small amounts of cool water, not ice-cold, and wet the paws and belly with cool water. Step 3: call the vet immediately, then the owner, and follow the vet's transport advice. Check: the record shows 32 C, 30 minutes, the signs, the call at 15:12 and that no medicine was given.",
  "Sort ten signs into watch, call owner or call vet.", "Nine of ten sorted correctly."),
 ("Risk, safety and rules", "Analyse", 4, "Risk covers animals, people and your business. List hazards for each route and home: traffic, other dogs, toxic plants, heat, ice, and escape through doors and gates. Score each by likelihood times harm, then add a control for the highest scores. Insure against injury and loss, learn registration needs from the competent authority, and keep clean records of incidents and near misses.",
  ["List hazards: traffic, other dogs, plants, heat, escape.", "Rank by likelihood x harm.", "Insure against injury and loss.", "Know registration needs from the competent authority.", "Keep clean records."],
  "Task: score an open-door hazard on scales of 1 to 5. Step 1: likelihood 3 and harm 5 (a dog on a road) give 3 x 5 = 15. Step 2: control: double-check locks and use a second lead clip, which lowers likelihood to 1. Step 3: new score = 1 x 5 = 5. Check: the reduction is 15 - 5 = 10 points, or 67 percent, and the control is written on the 15-item hazard list with the date it was checked.",
  "Complete a 15-item hazard list for a route and a home.", "Items rated; controls listed."),
 ("Pricing and running the service", "Create", 4, "A price must cover time, travel, supplies, insurance and idle gaps between visits, not only the hour with the pet. Add these costs, set a price per visit and per walk, and plan a week schedule with travel gaps so that it is feasible. Handle reviews and complaints calmly, keep written records, and follow tax and registration rules from the competent authority.",
  ["Add time, travel, supplies and insurance.", "Set a price per visit and per walk.", "Plan a week schedule with travel gaps.", "Handle reviews and complaints.", "Follow tax and registration rules."],
  "Task: price a 45-minute walk. Step 1: 45 minutes plus 15 minutes travel = 1 hour. Step 2: labour 500 RUB per hour plus 60 RUB for bags and insurance share gives a break-even of 560 RUB. Step 3: add a 20 percent margin: 560 x 1.2 = 672 RUB, rounded to 700 RUB. Step 4: four walks a day for 5 days = 20 walks, 20 hours, 14,000 RUB. Check: 700 - 560 = 140 RUB per walk, 25 percent over cost, and 20 hours fits one working week.",
  "Build a price list and a weekly plan.", "Prices cover costs; schedule is feasible.")],
 quiz=[("Food for a 10 kg dog at 25 g per kg?", "250 g a day."),
  ("Who can diagnose or medicate?", "Only a licensed vet."),
  ("Name two signs of stress in a dog.", "Stiff body, ears back, low tail or raised hackles."),
  ("What do you do in heat stress?", "Move to shade, cool gently, call the vet at once."),
  ("Why get emergency consent?", "So you can get care quickly."),
  ("Hazard score: likelihood 3 x harm 5?", "15."),
  ("Why log each visit?", "For proof of care and handover."),
  ("Which shampoo to use?", "Pet shampoo."),
  ("Never leave a pet where?", "In a hot car or tied up unattended."),
  ("Who to ask about permits?", "The competent Russian authority and a local adviser.")],
 rubric=[("Animal care", "Needs missed.", "Food, water, exercise and rest met.", "Adapts plan to the pet."),
  ("Handling safety", "Unsafe actions.", "Calm and correct.", "Reads and prevents trouble."),
  ("Records and contract", "Gaps.", "Complete forms.", "Clear handover to owner."),
  ("Health escalation", "Treats or ignores.", "Calls owner and vet correctly.", "Gives clear notes to the vet."),
  ("Pricing and risk", "Price loses money.", "Price covers costs.", "Plans insurance and schedule.")],
 ladder=["L1 Basic: feed and water a pet with guidance.", "L2 Awareness: explain basic needs and body signs.", "L3 Foundation: walk and care for a calm pet.", "L4 Practitioner: run visits and walks with records and contract.", "L5 Specialist: manage groups, grooming or special needs within the rules.", "L6 Advanced: lead a team and run a registered service.", "L7 Super expert: advise on welfare standards and training."],
 jobs=[("Pet sitter", "Cares for pets at home."), ("Dog walker", "Walks dogs safely."), ("Groomer", "Brushes and bathes pets."), ("Kennel assistant", "Helps in boarding."), ("Veterinary assistant trainee", "Supports a vet team.")],
 next="Childcare, Credit and Debit Counselling and Ceramic Studios."),
]
